// Enforce single successful initialization prior to any Text backend use.
int text_init = FUZZ_GET_ATTR_INT_GLOBAL("ImTui_Text_Init");
if (text_init) { /* avoid double-init of global backend state */ FUZZ_BAIL(); }

// Call the target function and validate success per API contract.
bool ok = ImTui_ImplText_Init();
if (!ok) { FUZZ_BAIL(); }

// Record initialized state for subsequent stubs.
FUZZ_SET_ATTR_INT_GLOBAL("ImTui_Text_Init", 1);

// Validation: ensured single init and checked return value; global state recorded for dependent calls.

// Must only shutdown after a successful init; enforce via global attribute.
if (!FUZZ_GET_ATTR_INT_GLOBAL("ImTui_Text_Init")) { FUZZ_BAIL(); }

ImTui_ImplText_Shutdown();

// Mark backend as de-initialized to prevent further Text calls until re-init.
FUZZ_SET_ATTR_INT_GLOBAL("ImTui_Text_Init", 0);

// Validation: guarded against shutdown without init and cleared global init state.

// NewFrame requires successful prior initialization.
if (!FUZZ_GET_ATTR_INT_GLOBAL("ImTui_Text_Init")) { FUZZ_BAIL(); }

ImTui_ImplText_NewFrame();

// Validation: ensured backend initialized before starting a new frame.
